  <section class="group">
    <h3 class="group__title">{{ section.title }}</h3>
    <div class="grid">
      @for (token of section.tokens; track token.name) {
        <div class="cell">
          @switch (section.kind) {
            @case ('radius') {
              <span class="box box--fill" [style.borderRadius]="'var(' + token.name + ')'"></span>
