    }
    .group {
      margin-bottom: 2rem;
    }
    .group__title {
      margin: 0 0 0.75rem;
      font-size: 0.95rem;
      font-weight: 600;
    }
    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
      gap: 0.75rem;
      align-items: start;
    }
    .card {
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
      position: relative;
      text-align: left;
      border: 1px solid #ececec;
      border-radius: 10px;
      background: #fff;
      padding: 0.75rem;
      font: inherit;
      cursor: pointer;
    }
    .card:hover {
      border-color: #cfcfcf;
    }
    .demo {
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 72px;
      max-height: 200px;
      overflow: auto;
      background: #f5f5f5;
      border-radius: 8px;
      padding: 0.5rem;
    }
    .gapwrap {
      display: flex;
      flex-wrap: wrap;
      width: 96px;
    }
    .gbox {
      width: 28px;
      height: 20px;
      border-radius: 4px;
      background: #7aa7ff;
    }
    .mzone {
      display: inline-flex;
      background: #dbe7ff;
      border-radius: 4px;
    }
    .mbox {
      width: 44px;
      height: 26px;
      border-radius: 4px;
      background: #2563eb;
