  color: #121212;
}
.note {
  margin: 0 0 1.5rem;
  font-size: 0.82rem;
  color: #757575;
}
code {
  font-family: ui-monospace, monospace;
}
.group {
  margin-bottom: 2rem;
}
.group__title {
  margin: 0 0 0.75rem;
  font-size: 0.95rem;
  font-weight: 600;
}
.bars {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.bar-row {
  position: relative;
  display: grid;
  grid-template-columns: 120px 90px 1fr;
  align-items: center;
  gap: 0.75rem;
  text-align: left;
  border: 1px solid #ececec;
  border-radius: 8px;
  background: #fff;
  padding: 0.6rem 0.75rem;
  font: inherit;
  cursor: pointer;
}
.bar-row:hover {
  border-color: #cfcfcf;
}
.bar-row__name {
  font-size: 0.78rem;
}
.bar-row__value {
  font-size: 0.72rem;
  color: #757575;
}
.bar-track {
  background: #e8f5ec;
  border-radius: 4px;
  overflow: hidden;
}
.bar-fill {
  display: block;
  height: 20px;
  border-radius: 4px;
  background: #0a7d34;
}
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 0.6rem;
}
.card {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  position: relative;
  text-align: left;
  border: 1px solid #ececec;
  border-radius: 10px;
  background: #fff;
  padding: 0.75rem;
  font: inherit;
  cursor: pointer;
}
.card:hover {
  border-color: #cfcfcf;
}
.card--value {
  flex-direction: row;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
}
.meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.meta__name {
  font-size: 0.78rem;
}
.meta__value {
  font-size: 0.72rem;
  color: #757575;
}
.truncate-demo {
  display: block;
  max-width: 260px;
  padding: 0.5rem;
  background: #f5f5f5;
  border-radius: 6px;
  font-size: 0.8rem;
}
.copied {
  position: absolute;
  right: 0.6rem;
  top: 0.5rem;
  font-size: 0.7rem;
  color: #0a7d34;
  opacity: 0;
  transition: opacity 0.15s;
}
.copied.show {
  opacity: 1;
}
.empty {
  color: #757575;
}

